package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen1Test {

    private KeyedObjects2D dataset;
    private static final Comparable COL_1 = "Column1";
    private static final Comparable COL_2 = "Column2";
    private static final Comparable ROW_1 = "Row1";
    private static final Comparable ROW_2 = "Row2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveColumn_Success() {
        // Arrange
        dataset.addObject("Val1_1", ROW_1, COL_1);
        dataset.addObject("Val1_2", ROW_1, COL_2);
        dataset.addObject("Val2_1", ROW_2, COL_1);
        dataset.addObject("Val2_2", ROW_2, COL_2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals("Val1_1", dataset.getObject(ROW_1, COL_1));

        // Act
        dataset.removeColumn(COL_1);

        // Assert
        assertEquals(1, dataset.getColumnCount());
        assertNull("Column 1 should be removed", dataset.getObject(ROW_1, COL_1));
        assertEquals("Val1_2", dataset.getObject(ROW_1, COL_2));
        assertEquals("Val2_2", dataset.getObject(ROW_2, COL_2));

        List columnKeys = dataset.getColumnKeys();
        assertFalse("Column 1 key should be gone", columnKeys.contains(COL_1));
        assertTrue("Column 2 key should remain", columnKeys.contains(COL_2));
    }

    @Test(expected = UnknownKeyException.class)
    public void testRemoveColumn_UnknownKeyThrowsException() {
        // Arrange
        dataset.addObject("Val1", ROW_1, COL_1);

        // Act
        // Using a key that hasn't been added should trigger the index != 0 check 
        // (assuming getColumnIndex returns -1 or something other than 0 for unknown keys)
        dataset.removeColumn("NonExistent");
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Arrange & Act & Assert
        // Should not throw exception if key is not found (it will throw UnknownKeyException)
        try {
            dataset.removeColumn(COL_1);
        } catch (UnknownKeyException e) {
            // Expected behavior for unknown keys in this implementation
        }
        assertEquals(0, dataset.getColumnCount());
    }

    @Test
    public void testRemoveColumn_RowWithoutSpecificColumn() {
        // Arrange
        // Add column 1 and 2, but Row 2 only has data for Column 2
        dataset.addObject("Val1_1", ROW_1, COL_1);
        dataset.addObject("Val1_2", ROW_1, COL_2);
        dataset.addObject("Val2_2", ROW_2, COL_2); 
        // Note: ROW_2 does not have COL_1

        // Act
        dataset.removeColumn(COL_1);

        // Assert
        assertEquals(1, dataset.getColumnCount());
        assertEquals("Val1_2", dataset.getObject(ROW_1, COL_2));
        assertEquals("Val2_2", dataset.getObject(ROW_2, COL_2));
    }

    @Test
    public void testRemoveColumn_ColumnIndexZeroLogic() {
        // The code contains a suspicious check: if (index != 0) throw Exception.
        // This implies only the column at index 0 can be removed via this method, 
        // OR there is a bug in the source code provided.
        // However, to maximize coverage, we test the branch.

        dataset.addObject("Val", ROW_1, COL_1);

        // If COL_1 is at index 0, it should succeed
        dataset.removeColumn(COL_1);
        assertEquals(0, dataset.getColumnCount());
    }
}
